CREATE TABLE IF NOT EXISTS orders(id VARCHAR(64) PRIMARY KEY,user_id VARCHAR(64) NOT NULL,request_key VARCHAR(100) NOT NULL,request_json TEXT NOT NULL,quote_json TEXT,address_json TEXT NOT NULL,total INT DEFAULT 0 NOT NULL,status VARCHAR(20) NOT NULL,expires_at TIMESTAMP NOT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,carrier VARCHAR(64),tracking_no VARCHAR(100),last_error VARCHAR(1000),UNIQUE(user_id,request_key));
CREATE INDEX IF NOT EXISTS idx_order_operations ON orders(status,expires_at);
CREATE TABLE IF NOT EXISTS order_events(id VARCHAR(64) PRIMARY KEY,order_id VARCHAR(64) NOT NULL,kind VARCHAR(32) NOT NULL,detail VARCHAR(1000),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);